lucide.createIcons();
const progressFill=document.getElementById('progressFill');
window.addEventListener('scroll',()=>{const s=window.scrollY,d=document.documentElement.scrollHeight-window.innerHeight;if(d>0)progressFill.style.width=`${(s/d)*100}%`;});
window.openModal=(id)=>{const m=document.getElementById(id);if(m){m.classList.add('is-open');document.body.style.overflow='hidden';}};
window.closeModal=(id)=>{const m=document.getElementById(id);if(m){m.classList.remove('is-open');document.body.style.overflow='';const v=m.querySelector('video');if(v)v.pause();}};
document.querySelectorAll('.overlay').forEach(o=>o.addEventListener('click',e=>{if(e.target===o)closeModal(o.id);}));
window.toggleHs=(btn,id)=>{const pop=document.getElementById(id),was=pop.classList.contains('is-open'),sc=btn.closest('.hs-scene');sc.querySelectorAll('.hs-popover').forEach(p=>p.classList.remove('is-open'));sc.querySelectorAll('.btn,.hs-btn').forEach(b=>b.classList.remove('is-active'));if(!was){pop.classList.add('is-open');btn.classList.add('is-active');}};
window.closeHs=(id)=>{const p=document.getElementById(id);if(p){p.classList.remove('is-open');const sc=p.closest('.hs-scene');if(sc)sc.querySelectorAll('.btn,.hs-btn').forEach(b=>b.classList.remove('is-active'));}};
window.switchTab=(tab,panelId)=>{const tabs=tab.closest('.tabs');tabs.querySelectorAll('.tabs__tab').forEach(t=>{if(t.closest('.tabs')===tabs){t.classList.remove('is-active');t.setAttribute('aria-selected','false');}});tabs.querySelectorAll('.tabs__panel').forEach(p=>{if(p.closest('.tabs')===tabs)p.classList.remove('is-active');});tab.classList.add('is-active');tab.setAttribute('aria-selected','true');const panel=document.getElementById(panelId);if(panel)panel.classList.add('is-active');};
window.crNav=(btn,dir)=>{const car=btn.closest('.carousel'),slides=Array.from(car.querySelectorAll('.carousel__slide')),dots=Array.from(car.querySelectorAll('.carousel__dot'));let cur=slides.findIndex(s=>s.classList.contains('is-active'));if(cur<0)cur=0;const next=(cur+dir+slides.length)%slides.length;slides[cur].classList.remove('is-active');slides[next].classList.add('is-active');if(dots[cur])dots[cur].classList.remove('is-active');if(dots[next])dots[next].classList.add('is-active');const counter=car.querySelector('.carousel__counter');if(counter)counter.textContent=`${next+1} / ${slides.length}`;car.querySelectorAll('.hs-popover.is-open').forEach(p=>p.classList.remove('is-open'));};
window.crGoTo=(dot,idx)=>{const car=dot.closest('.carousel'),slides=Array.from(car.querySelectorAll('.carousel__slide')),dots=Array.from(car.querySelectorAll('.carousel__dot'));const cur=slides.findIndex(s=>s.classList.contains('is-active'));if(cur===idx)return;slides[cur].classList.remove('is-active');slides[idx].classList.add('is-active');if(dots[cur])dots[cur].classList.remove('is-active');if(dots[idx])dots[idx].classList.add('is-active');const counter=car.querySelector('.carousel__counter');if(counter)counter.textContent=`${idx+1} / ${slides.length}`;car.querySelectorAll('.hs-popover.is-open').forEach(p=>p.classList.remove('is-open'));};
window.toggleCrPop=(btn,id)=>{const pop=document.getElementById(id),was=pop.classList.contains('is-open');btn.closest('.carousel').querySelectorAll('.hs-popover').forEach(p=>p.classList.remove('is-open'));if(!was)pop.classList.add('is-open');};
window.closeCrPop=(id)=>{document.getElementById(id).classList.remove('is-open');};
const sidebarLinks=document.querySelectorAll(".sidebar-nav__link");if(sidebarLinks.length){const sections=document.querySelectorAll("section[id]");const obs=new IntersectionObserver((entries)=>{entries.forEach(e=>{if(e.isIntersecting){sidebarLinks.forEach(l=>l.classList.remove("is-active"));const a=document.querySelector(".sidebar-nav__link[href=\"#"+e.target.id+"\"]");if(a)a.classList.add("is-active");}});},{rootMargin:"-15% 0px -75% 0px"});sections.forEach(s=>obs.observe(s));}
const _btt=document.getElementById("backToTop");window.addEventListener("scroll",()=>{_btt&&(_btt.classList.toggle("is-visible",window.scrollY>300))});window.openSidebar=()=>{const s=document.querySelector(".sidebar"),o=document.getElementById("sidebarOverlay");s&&s.classList.add("is-open");o&&o.classList.add("is-open")};window.closeSidebar=()=>{const s=document.querySelector(".sidebar"),o=document.getElementById("sidebarOverlay");s&&s.classList.remove("is-open");o&&o.classList.remove("is-open")};document.querySelectorAll(".sidebar-nav__link").forEach(a=>a.addEventListener("click",closeSidebar));
